// A router in the shape most HTTP frameworks share: a registration takes a
// path and then its handlers, and a handler is handed the request and the
// response it answers through. Vendored as a dependency, because a type's
// declaration ORIGIN is part of what tells transport apart from a payload.
export interface Req<B = unknown> {
  body: B;
  params: Record<string, string>;
}

export interface Res {
  statusCode: number;
  status(code: number): this;
  setHeader(name: string, value: string): this;
  getHeader(name: string): string | undefined;
  json(body?: unknown): this;
  send(body?: unknown): this;
  end(): void;
}

export type Next = (error?: unknown) => void;

export type Handler = (req: Req<any>, res: Res, next: Next) => unknown;

export interface Ctx {
  req: { raw: Request };
}

export interface Router {
  get(path: string, ...handlers: Handler[]): this;
  post(path: string, ...handlers: Handler[]): this;
  delete(path: string, ...handlers: Handler[]): this;
  all(path: string, handler: (c: Ctx) => Response | Promise<Response>): this;
  use(path: string, router: Router): this;
}

export function createRouter(): Router;

// Something that answers a platform request with a platform response.
export interface Engine {
  handle(request: Request): Response | Promise<Response>;
}

export function createEngine(): Engine;
